require "/home/appontrack/public_html/saas/console/_core/Bootstrap.php";
require "/home/appontrack/public_html/saas/console/_core/WhatsAppSupport.php";
try {
 init_schema();
 $q=all("SELECT id,account_id,state,phone_number_id,onboarding_method,webhook_relay_enabled,source_callback_url,last_webhook_at,ai_enabled,ai_agent_id FROM wa_connections ORDER BY id DESC LIMIT 20");
 $out=[];
 foreach($q as $c){
  $counts=one("SELECT COUNT(*) n FROM wa_conversations WHERE connection_id=? AND account_id=?",[(int)$c["id"],(int)$c["account_id"]]);
  $out[]=["kind"=>(string)($c["onboarding_method"]??""),"state"=>(string)$c["state"],
    "pending_phone"=>str_starts_with((string)$c["phone_number_id"],"pending_"),
    "relay_enabled"=>(bool)$c["webhook_relay_enabled"],
    "source_host"=>parse_url((string)($c["source_callback_url"]??""),PHP_URL_HOST)?:null,
    "has_last_webhook"=>!empty($c["last_webhook_at"]),
    "conversation_count"=>(int)$counts["n"],"ai_enabled"=>(bool)$c["ai_enabled"],
    "has_agent"=>(int)$c["ai_agent_id"]>0];
 }
 echo json_encode(["connections"=>count($out),"details"=>$out],JSON_THROW_ON_ERROR);
}catch(Throwable $e){echo json_encode(["error"=>get_class($e),"message"=>mb_substr($e->getMessage(),0,100)]);exit(2);}
